205	// handleUI2IntruderControl serves POST /ui2/intruder/{id}/{action}: pause/resume/stop one attack.
206	func (s *Server) handleUI2IntruderControl(w http.ResponseWriter, r *http.Request) {
207		id := r.PathValue("id")
208		action := r.PathValue("action")
209		if action != "pause" && action != "resume" && action != "stop" {
210			http.Error(w, "unknown attack action", http.StatusBadRequest)
211			return
212		}
213		path := "/api/intruder/attacks/" + id + "/" + action
214		_, errText := s.ui2APIResult(http.MethodPost, path, map[string]any{})
215		attacks, _ := s.ui2APIResult(http.MethodGet, "/api/intruder/attacks", nil)
216		wordlists, _ := s.ui2APIResult(http.MethodGet, "/api/wordlists", nil)
217		model := map[string]any{"attacks": attacks, "wordlists": wordlists, "error": errText, "action": action, "id": id}
218		model["base_exchange"], model["base_msgid"], model["base_request"] = ui2LatestExchange(s)
219		ui2Fragment(w, r, "burpsy /ui2/ — Intruder", "intruder", ui2Exec("intruder.html", model))
220	}
