242	// ui2IntruderRunPayload builds the /api/intruder/run body from the launch form.
243	func (s *Server) ui2IntruderRunPayload(r *http.Request) (map[string]any, string) {
244		run := map[string]any{
245			"msg_id": ui2Atoi(r.PostFormValue("msg_id")),
246			"target": r.PostFormValue("target"),
247			"mode":   "sniper",
248		}
249		if r.PostFormValue("target") == "" {
250			if _, _, raw := ui2LatestExchange(s); raw != "" {
251				run["target"] = ui2HostFromRequest(raw)
252			}
253		}
254		// Payloads: one per line from the textarea.
255		var payloads []string
256		for _, line := range strings.Split(r.PostFormValue("payloads"), "\n") {
257			if p := strings.TrimRight(line, "\r"); p != "" {
258				payloads = append(payloads, p)
259			}
260		}
261		if len(payloads) > 0 {
262			run["payloads"] = payloads
263		}
264		// Points: checkbox list points[].
265		var points []int
266		for _, v := range r.PostForm["point"] {
267			if n, err := strconv.Atoi(v); err == nil {
268				points = append(points, n)
269			}
270		}
271		if r.PostFormValue("all_points") == "on" {
272			// "all" selects the discovery CONFIG at run time (intruderPointConfig(true, ...) — the
273			// same config the points listing used); it does not select the points: selectPoints
274			// refuses a run without an explicit selection ("no insertion point selected"). So the
275			// payload needs both: all:true to keep the discovery config, and the selection as
276			// explicit indexes.
277			run["all"] = true
278			if len(points) > 0 {
279				// The confirm fragment posts the minted selection back: those indexes ARE the
280				// confirmed set — the operator was shown exactly these, and the gate's digest
281				// binds the token to them. Re-resolving here would make the posted inputs inert
282				// and let a changed message silently widen the confirmed attack.
283				run["points"] = points
284			} else {
285				// A hand-built post without the fragment's fields: resolve the selection the way
286				// the confirm step would have.
287				n, errText := s.ui2DiscoveredPointCount(r)
288				if errText != "" {
289					return run, errText
290				}
291				if n == 0 {
292					// /api/intruder/run would refuse this launch with "no insertion point selected";
293					// say so on the form instead of minting a token for a call that cannot succeed.
294					return run, "no insertion points discovered on message " + r.PostFormValue("msg_id") +
295						" — pick a request whose parameters, cookies or body can carry payloads"
296				}
297				idx := make([]int, n)
298				for i := range idx {
299					idx[i] = i
300				}
301				run["points"] = idx
302			}
303		} else if len(points) > 0 {
304			run["points"] = points
305		} else {
306			// An unchecked "all points" with no explicit indexes selected nothing. Resolving every
307			// point anyway — the previous behaviour — turned "I want to choose" into the widest
308			// possible attack without a word; refuse and name the ways to make a selection.
309			return run, `no insertion points selected: check "all points" or select at least one point`
310		}
311		if r.PostFormValue("payload_placement") != "" {
312			run["payload_placement"] = r.PostFormValue("payload_placement")
313		}
314		return run, ""
315	}
316	
317	// ui2DiscoveredPointCount counts the insertion points /api/intruder/points discovers for the
318	// form's message; the error text is the API's own (unknown message, bad placement) when it
319	// refused, and "" when it answered — 0 then genuinely means nothing to inject into.
320	func (s *Server) ui2DiscoveredPointCount(r *http.Request) (int, string) {
321		disc, errText := s.ui2APIResult(http.MethodPost, "/api/intruder/points", map[string]any{
322			"msg_id":            ui2Atoi(r.PostFormValue("msg_id")),
323			"all":               true,
324			"payload_placement": r.PostFormValue("payload_placement"),
325		})
326		if errText != "" {
327			return 0, errText
328		}
329		list, ok := disc.([]any)
330		if !ok {
331			return 0, "point discovery answered in a shape the page does not understand"
332		}
333		return len(list), ""
334	}
335	
336	func ui2Atoi(s string) uint64 {
337		n, _ := strconv.ParseUint(s, 10, 64)
338		return n
339	}
340	
341	// ui2ParseCount parses an operator-entered form count. An unparseable value or one past
342	// the ceiling is refused with the field named, never silently clamped into a body the
343	// review gate would then mint as if the operator had asked for it. The ceiling keeps the
344	// uint64->int conversion wrap-free (G115); an empty field means "absent" and the API's
345	// own validation decides what 0 means there.
346	func ui2ParseCount(field, s string) (int, string) {
347		const ceiling = 1 << 20
348		if s == "" {
349			return 0, ""
350		}
351		n, err := strconv.ParseUint(s, 10, 64)
352		if err != nil {
353			return 0, field + " must be a whole number"
354		}
355		if n > ceiling {
356			return 0, fmt.Sprintf("%s must be at most %d", field, ceiling)
357		}
358		return int(n), ""
359	}
