368	// ui2SequencerModel is the page model every Sequencer handler re-renders with: the capture
369	// list and analysis settings, whether any capture is running (drives the control buttons),
370	// and the latest proxy exchange as the start form's prefilled request.
371	func (s *Server) ui2SequencerModel() map[string]any {
372		caps, _ := s.ui2APIResult(http.MethodGet, "/api/sequencer/capture/", nil)
373		settings, _ := s.ui2APIResult(http.MethodGet, "/api/sequencer/settings", nil)
374		model := map[string]any{"captures": caps, "settings": settings}
375		anyRunning := false
376		if m, ok := caps.(map[string]any); ok {
377			if list, ok := m["captures"].([]any); ok {
378				for _, c := range list {
379					if cm, ok := c.(map[string]any); ok {
380						if b, ok := cm["capturing"].(bool); ok && b {
381							anyRunning = true
382						}
383					}
384				}
385			}
386		}
387		model["any_running"] = anyRunning
388		_, _, raw := ui2LatestExchange(s)
389		model["base_request"] = raw
390		return model
391	}
