426	// handleUI2SequencerCapture serves POST /ui2/sequencer/capture/{action}. "confirm" mints the
427	// one-time review for the exact start call (/api/sequencer/capture is riskAttack - the gate
428	// must see the same body the operator reviewed); "run" spends it; pause/resume/stop drive a
429	// running capture through the API's own control verbs, which are riskRead because stopping
430	// work cannot attack anything.
431	func (s *Server) handleUI2SequencerCapture(w http.ResponseWriter, r *http.Request) {
432		_ = r.ParseForm()
433		switch r.PathValue("action") {
434		case "confirm":
435			payload, errText := ui2SequencerCapturePayload(r)
436			if errText != "" {
437				model := s.ui2SequencerModel()
438				model["error"] = errText
439				ui2Fragment(w, r, "burpsy /ui2/ — Sequencer", "sequencer", ui2Exec("sequencer.html", model))
440				return
441			}
442			body, _ := ui2Marshal(payload)
443			token, preview, errText := s.ui2MintConfirm("/api/sequencer/capture", http.MethodPost, "/api/sequencer/capture", body)
444			model := map[string]any{
445				"token": token, "preview": preview, "error": errText,
446				// The one-line preview is truncated for display; a confirmation gate has to
447				// show the WHOLE exact body it binds, so the sheet carries it in full.
448				"full_body": string(body),
449				"target":    r.PostFormValue("target"), "protocol": r.PostFormValue("protocol"),
450				"count": r.PostFormValue("count"), "delay_ms": r.PostFormValue("delay_ms"),
451				"threads": r.PostFormValue("threads"), "kind": r.PostFormValue("kind"),
452				"name": r.PostFormValue("name"), "pattern": r.PostFormValue("pattern"),
453				"request": r.PostFormValue("request"),
454			}
455			w.Header().Set("Content-Type", "text/html; charset=utf-8")
456			_, _ = w.Write([]byte(ui2Exec("sequencer_confirm.html", model)))
457		case "run":
458			// No dispatch at all without a token: spending a confirmation on a body the operator
459			// never reviewed is the failure this branch exists to prevent.
460			var errText string
461			payload, valErr := ui2SequencerCapturePayload(r)
462			switch {
463			case valErr != "":
464				errText = valErr
465			case r.PostFormValue("token") == "":
466				errText = "no confirmation token: review the capture first"
467			default:
468				_, errText = s.ui2DispatchConfirmed(http.MethodPost, "/api/sequencer/capture", payload, r.PostFormValue("token"))
469			}
470			// The model is built after the dispatch, not before: the operator just started a
471			// capture and the response is the first place they look for its row.
472			model := s.ui2SequencerModel()
473			model["error"] = errText
474			ui2Fragment(w, r, "burpsy /ui2/ — Sequencer", "sequencer", ui2Exec("sequencer.html", model))
475		case "pause", "resume", "stop":
476			_, errText := s.ui2APIResult(http.MethodPost, "/api/sequencer/capture/"+r.PathValue("action"), map[string]any{})
477			model := s.ui2SequencerModel()
478			model["error"] = errText
479			ui2Fragment(w, r, "burpsy /ui2/ — Sequencer", "sequencer", ui2Exec("sequencer.html", model))
480		default:
481			http.Error(w, "unknown capture action", http.StatusBadRequest)
482		}
483	}
