485	// handleUI2SequencerAnalyse serves POST /ui2/sequencer/analyse (paste mode, riskRead — no
486	// confirmation needed) rendering the report.
487	func (s *Server) handleUI2SequencerAnalyse(w http.ResponseWriter, r *http.Request) {
488		_ = r.ParseForm()
489		var tokens []string
490		for _, line := range strings.Split(r.PostFormValue("tokens"), "\n") {
491			if t := strings.TrimSpace(line); t != "" {
492				tokens = append(tokens, t)
493			}
494		}
495		body := map[string]any{"tokens": tokens, "encoding": r.PostFormValue("encoding")}
496		rep, errText := s.ui2APIResult(http.MethodPost, "/api/sequencer/analyse", body)
