	{"uppercase", "Uppercase"}, {"lowercase", "Lowercase"}, {"encode", "Encode"}, {"decode", "Decode"},
	{"hash", "Hash"}, {"skip_if_matches", "Skip if it matches"}, {"normalize", "Unicode normalization"},
