	if i < 0 {
		t.Fatalf("no run form in the review sheet: %.400s", frag)
	}
	out := url.Values{}
	for _, m := range ui2HiddenInputRe.FindAllStringSubmatch(frag[i:], -1) {
		out.Add(html.UnescapeString(m[1]), html.UnescapeString(m[2]))
	}
	return out
}

